-- SCP Tactical Panel -- Roblox Studio: LocalScript em StarterPlayerScripts -- Equipes: GUARD, MTF e SCP local Players = game:GetService("Players") local UserInputService = game:GetService("UserInputService") local LocalPlayer = Players.LocalPlayer local PlayerGui = LocalPlayer:WaitForChild("PlayerGui") -- CONFIGURAÇÃO DAS EQUIPES local TEAM_CONFIG = { ["GUARD"] = { Color = Color3.fromRGB(100, 200, 255) }, ["MTF"] = { Color = Color3.fromRGB(40, 80, 180) }, ["SCP"] = { Color = Color3.fromRGB(255, 100, 190) } } -- ESTADO DOS DESTAQUES local ESP_ENABLED = { GUARD = false, MTF = false, SCP = false } local GUI_NAME = "SCPTacticalPanel" local HIGHLIGHT_NAME = "SCPPanelHighlight" -- REMOVER INTERFACE ANTIGA local oldGui = PlayerGui:FindFirstChild(GUI_NAME) if oldGui then oldGui:Destroy() end -- CRIAR INTERFACE local Gui = Instance.new("ScreenGui") Gui.Name = GUI_NAME Gui.ResetOnSpawn = false Gui.Parent = PlayerGui local Panel = Instance.new("Frame") Panel.Name = "Panel" Panel.Size = UDim2.fromOffset(290, 260) Panel.Position = UDim2.new(0, 20, 0.3, 0) Panel.BackgroundColor3 = Color3.fromRGB(25, 25, 40) Panel.BorderSizePixel = 0 Panel.Active = true Panel.Parent = Gui local panelCorner = Instance.new("UICorner") panelCorner.CornerRadius = UDim.new(0, 12) panelCorner.Parent = Panel -- CABEÇALHO local Header = Instance.new("TextButton") Header.Name = "Header" Header.Size = UDim2.new(1, 0, 0, 44) Header.BackgroundColor3 = Color3.fromRGB(65, 55, 130) Header.Text = "SCP TACTICAL PANEL [-]" Header.TextColor3 = Color3.new(1, 1, 1) Header.TextSize = 16 Header.Font = Enum.Font.GothamBold Header.Parent = Panel local headerCorner = Instance.new("UICorner") headerCorner.CornerRadius = UDim.new(0, 12) headerCorner.Parent = Header -- ARRASTAR COM MOUSE OU TOQUE local dragging = false local dragInput local dragStart local startPosition Header.InputBegan:Connect(function(input) if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = true dragStart = input.Position startPosition = Panel.Position input.Changed:Connect(function() if input.UserInputState == Enum.UserInputState.End then dragging = false end end) end end) Header.InputChanged:Connect(function(input) if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then dragInput = input end end) UserInputService.InputChanged:Connect(function(input) if dragging and ( input == dragInput or input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch ) then local delta = input.Position - dragStart Panel.Position = UDim2.new( startPosition.X.Scale, startPosition.X.Offset + delta.X, startPosition.Y.Scale, startPosition.Y.Offset + delta.Y ) end end) -- MINIMIZAR E RESTAURAR local minimized = false Header.Activated:Connect(function() minimized = not minimized for _, child in ipairs(Panel:GetChildren()) do if child ~= Header and child:IsA("GuiObject") then child.Visible = not minimized end end Panel.Size = minimized and UDim2.fromOffset(290, 44) or UDim2.fromOffset(290, 260) Header.Text = minimized and "SCP TACTICAL PANEL [+]" or "SCP TACTICAL PANEL [-]" end) -- CRIAR BOTÕES local function createButton(text, y, callback, color) local button = Instance.new("TextButton") button.Size = UDim2.new(1, -20, 0, 38) button.Position = UDim2.fromOffset(10, y) button.BackgroundColor3 = color or Color3.fromRGB(55, 55, 75) button.TextColor3 = Color3.new(1, 1, 1) button.TextSize = 14 button.Font = Enum.Font.Gotham button.Text = text button.Parent = Panel local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0, 8) corner.Parent = button button.Activated:Connect(function() callback(button) end) return button end -- ATUALIZAR DESTAQUES local function updateESP() for _, player in ipairs(Players:GetPlayers()) do if player ~= LocalPlayer then local character = player.Character if character then local highlight = character:FindFirstChild(HIGHLIGHT_NAME) local teamName = player.Team and player.Team.Name local config = teamName and TEAM_CONFIG[teamName] if config and ESP_ENABLED[teamName] then if not highlight then highlight = Instance.new("Highlight") highlight.Name = HIGHLIGHT_NAME highlight.Adornee = character highlight.Parent = character end highlight.FillColor = config.Color highlight.OutlineColor = config.Color highlight.FillTransparency = 0.5 highlight.OutlineTransparency = 0 highlight.Enabled = true elseif highlight then highlight:Destroy() end end end end end -- LIGAR E DESLIGAR ESP local function toggleESP(teamName, button) ESP_ENABLED[teamName] = not ESP_ENABLED[teamName] button.Text = "ESP " .. teamName .. (ESP_ENABLED[teamName] and " — LIGADO" or " — DESLIGADO") updateESP() end createButton( "ESP GUARD — DESLIGADO", 55, function(button) toggleESP("GUARD", button) end, TEAM_CONFIG.GUARD.Color ) createButton( "ESP MTF — DESLIGADO", 100, function(button) toggleESP("MTF", button) end, TEAM_CONFIG.MTF.Color ) createButton( "ESP SCP — DESLIGADO", 145, function(button) toggleESP("SCP", button) end, TEAM_CONFIG.SCP.Color ) createButton( "Atualizar destaques", 190, function() updateESP() end ) -- ACOMPANHAR JOGADORES local function connectPlayer(player) player.CharacterAdded:Connect(function() task.wait(0.5) updateESP() end) player:GetPropertyChangedSignal("Team"):Connect(updateESP) end for _, player in ipairs(Players:GetPlayers()) do connectPlayer(player) end Players.PlayerAdded:Connect(function(player) connectPlayer(player) updateESP() end) Players.PlayerRemoving:Connect(function() task.defer(updateESP) end) print( "SCP Tactical Panel iniciado: GUARD, MTF e SCP." ) 
